"""Published prerequisites restore generated bytes, never source or CI artifacts."""
# cspell:words importlib
import copy
import hashlib
import importlib.util
import io
import json
from pathlib import Path
import tarfile
import tempfile
import unittest

def load(name,file):
    spec=importlib.util.spec_from_file_location(name,Path(__file__).with_name(file))
    value=importlib.util.module_from_spec(spec);spec.loader.exec_module(value);return value

module=load('release_restore_contract','incremental-release-materialize.py')
fixtures=load('release_restore_fixture','incremental-chain-plan.test.py')

def archive(name='a',file='package/dist/index.js',kind=None):
    output=io.BytesIO()
    with tarfile.open(fileobj=output,mode='w:gz') as target:
        for path,body in [('package/package.json',json.dumps({'name':name,'version':'1.0.0'}).encode()),(file,b'original release JS')]:
            row=tarfile.TarInfo(path);row.size=len(body)
            if kind is not None and path==file:row.type=kind;row.linkname='outside'
            target.addfile(row,io.BytesIO(body))
    return output.getvalue()

class Contracts(unittest.TestCase):
    def fixture(self):
        files,family,identity=fixtures.fixture();files['crates/core/src/lib.rs']+=b'\npub const VERSION: &str = "0.5.4";\n'
        files['docs/releases/v2-candidate.json']=json.dumps(family).encode()
        ledger,anchor=fixtures.baseline(files,family)
        source={**identity,'files':files,'modes':fixtures.modes(files)}
        original=copy.deepcopy(source);original['sha']=ledger['sourceSHA'];original['tree']=ledger['sourceTree']
        body=archive();ledger['packages']['npm:a']['archiveSha256']=hashlib.sha256(body).hexdigest()
        for row in ledger['packages'].values():row.update({'originSourceSHA':original['sha'],'originRunId':2,'originAttempt':1})
        anchor['registryChecksums']['npm:a']=hashlib.sha256(body).hexdigest();anchor['ledgerSha256']=module.entry.chain.digest(ledger)
        baseline={'transaction':'f'*64,'stateRevision':'1'*40,'source':original,'ledger':ledger,'anchor':anchor}
        pkg=json.loads(source['files']['packages/b/package.json']);pkg['version']='1.0.1';source['files']['packages/b/package.json']=json.dumps(pkg).encode()
        source['files']['packages/b/src/index.ts']+=b' changed'
        family['npm']['primary'][1]['version']='1.0.1';source['files']['docs/releases/v2-candidate.json']=json.dumps(family).encode()
        selection={'publicationScope':'npm','planHash':'a'*64}
        return source,baseline,selection,body
    def test_js_only_restore_is_disabled_and_preserves_source(self):
        source,baseline,selection,body=self.fixture()
        with tempfile.TemporaryDirectory(prefix='farm-release-restore-') as directory:
            root=Path(directory).resolve();source_file=root/'packages/a/src/index.ts';source_file.parent.mkdir(parents=True);source_file.write_bytes(source['files']['packages/a/src/index.ts'])
            calls=[]
            def fetch(row):calls.append(row['identity']);return body
            with self.assertRaisesRegex(ValueError,'restore is disabled'):module.restore(source,selection,baseline,root,fetch)
            self.assertEqual(calls,[])
            self.assertFalse((root/'packages/a/dist/index.js').exists())
            self.assertEqual(source_file.read_bytes(),source['files']['packages/a/src/index.ts'])
            self.assertEqual(source_file.read_bytes(),source['files']['packages/a/src/index.ts'])
    def test_wrong_bytes_or_plan_cannot_restore_any_prerequisite(self):
        source,baseline,selection,body=self.fixture()
        with tempfile.TemporaryDirectory(prefix='farm-release-restore-') as directory:
            with self.assertRaisesRegex(ValueError,'restore is disabled'):module.restore(source,selection,baseline,directory,lambda _:body+b'changed')
            selection['planHash']='0'*64
            with self.assertRaisesRegex(ValueError,'restore is disabled'):module.restore(source,selection,baseline,directory,lambda _:body)
    def test_unsafe_tar_paths_and_links_are_rejected_before_materialization(self):
        for file,kind in [('package/../../outside',None),('package/dist/link',tarfile.SYMTYPE),('package/AUX',None)]:
            with self.assertRaises((ValueError,AssertionError)):module.members(archive(file=file,kind=kind))
    def test_existing_different_generated_bytes_are_never_overwritten(self):
        source,baseline,selection,body=self.fixture()
        with tempfile.TemporaryDirectory(prefix='farm-release-restore-') as directory:
            file=Path(directory)/'packages/a/dist/index.js';file.parent.mkdir(parents=True);file.write_bytes(b'other build')
            with self.assertRaisesRegex(ValueError,'restore is disabled'):module.restore(source,selection,baseline,directory,lambda _:body)
            with self.assertRaisesRegex(ValueError,'overwrite'):module.write_generated(Path(directory).resolve(),'packages/a/dist/index.js',b'changed',{})
            self.assertEqual(file.read_bytes(),b'other build')

    def test_cli_rejects_before_credentials_or_registry_access(self):
        with self.assertRaisesRegex(ValueError,'restore is disabled'):module.main()

if __name__=='__main__':unittest.main(verbosity=2)
